-- Workout and nutrition library. Run once in the Supabase SQL editor. Safe to run again.

create table if not exists public.exercise_library (
  id text primary key,
  split text not null,
  day_tag text not null,
  slot int not null,
  variation int not null default 0,
  lead boolean not null default false,
  compound boolean not null default false,
  core boolean not null default false,
  level_min text not null default 'beginner',
  goals text[] not null default array['fat','muscle','recomp']::text[],
  name_full text not null,
  name_limited text not null,
  name_home text not null,
  sets int not null default 3,
  reps text not null,
  rest_seconds int not null default 60,
  note text not null default '',
  anim text not null default 'press',
  prime text not null default '',
  help text not null default '',
  priority int not null default 0
);

create table if not exists public.food_library (
  id text primary key,
  name text not null,
  kcal numeric not null,
  protein numeric not null,
  carbs numeric not null,
  fat numeric not null,
  piece_name text,
  piece_grams numeric
);

create table if not exists public.meal_library (
  id text primary key,
  slot text not null,
  title text not null,
  emoji text not null default '🍽️',
  vegetarian boolean not null default false,
  protein_id text not null,
  carb_id text not null,
  extras text[] not null default array[]::text[],
  tip text not null default ''
);

alter table public.exercise_library enable row level security;
alter table public.food_library enable row level security;
alter table public.meal_library enable row level security;

drop policy if exists "Public read exercise library" on public.exercise_library;
drop policy if exists "Public read food library" on public.food_library;
drop policy if exists "Public read meal library" on public.meal_library;

create policy "Public read exercise library" on public.exercise_library for select to anon, authenticated using (true);
create policy "Public read food library" on public.food_library for select to anon, authenticated using (true);
create policy "Public read meal library" on public.meal_library for select to anon, authenticated using (true);

grant select on public.exercise_library to anon, authenticated;
grant select on public.food_library to anon, authenticated;
grant select on public.meal_library to anon, authenticated;

on conflict (id) do nothing;

on conflict (id) do nothing;

on conflict (id) do nothing;
